            const points = gradePoints[gradeValue];

            if (!isNaN(unitValue) && unitValue > 0) {
                const coursePoints = unitValue * points;
                const isPassing = gradeValue !== 'F' && gradeValue !== 'E';

                totalUnits += unitValue;
                totalPoints += coursePoints;
                validCourses++;

                if (isPassing) {
                    passingCourses++;
